# Generated by manage.py generate_test_cases.
from pydantic import ValidationError

from bloomerp.dataviews.kanban.config import KanbanDataView
from bloomerp.tests.base import BloomerpDataviewTestCase


class TestKanbanDataview(BloomerpDataviewTestCase):
    dataview_key = "kanban"

    def test_rejects_ambiguous_groups_and_unsafe_colours(self) -> None:
        """
        Use case: Developers configure overlapping destinations or invalid CSS colours.
        Expected result: Configuration validation rejects ambiguous and unsafe inputs.
        """
        # 1. Reject values assigned to more than one custom lane.
        with self.assertRaises(ValidationError):
            KanbanDataView(
                custom_groupings={"First": ["applied"], "Second": ["applied"]}
            )
        # 2. Reject empty groups and unnamed lanes.
        for grouping in [{"First": []}, {" ": ["applied"]}]:
            with self.assertRaises(ValidationError):
                KanbanDataView(custom_groupings=grouping)
        # 3. Reject CSS expressions instead of six-digit hex colours.
        with self.assertRaises(ValidationError):
            KanbanDataView(lane_colouring={"applied": "red; background: url(example)"})
